mapper.select:
SELECT goods_no, goods_discount, goods_code, goods_name, goods_price, poster_url, subposter_url, b.brand_name, c.category_name FROM goods g, brand b, category c WHERE g.brand_no = b.brand_no AND g.category_no = c.category_no
AND g.category_no = #{category}
AND g.brand_no = #{brand}
AND g.goods_name LIKE '%' || #{fd} || '%'
ORDER BY g.goods_no DESC OFFSET #{start} ROWS FETCH NEXT 10 ROWS ONLY

SELECT CEIL(COUNT(*)/10.0) FROM goods g, brand b, category c WHERE g.brand_no = b.brand_no AND g.category_no = c.category_no
AND g.category_no = #{category}
AND g.brand_no = #{brand}
AND g.goods_name LIKE '%' || #{fd} || '%'

SELECT no, goods_no, goods_size, quantity, created_at, updated_at
 FROM stock
WHERE goods_no = #{no}

select o.order_no, o.id, g.goods_name, d.sizes, d.quantity, to_char(o.order_date, 'yyyy-mm-dd') as dbday, d.status, d.order_detail_no, g.goods_no from orders o, order_detail d, goods g where o.order_no = d.order_no and d.goods_no = g.goods_no
AND d.status = #{status}
AND o.id = #{memberId}
order by o.order_date desc, o.id

	select CEIL(count(*)/10.0)
	from orders o, order_detail d, goods g
	where o.order_no = d.order_no
	and d.goods_no = g.goods_no

        AND d.status = #{status}


        AND o.id = #{memberId}

SELECT quantity, no 
 FROM STOCK 
WHERE goods_no = #{goods_no} 
and goods_size = #{sizes}

