mapper.select:
SELECT q.qna_no, q.parent_no, q.type, q.subject, q.content, q.status, q.id, TO_CHAR(q.CREATED_AT, 'yyyy-mm-dd') AS dbday, q.goods_no, g.goods_name FROM qna q JOIN goods g ON q.goods_no = g.goods_no WHERE q.type != '관리자답변'
AND q.status = #{status}
AND q.id = #{id}
ORDER BY q.qna_no DESC OFFSET #{start} ROWS FETCH NEXT 10 ROWS ONLY

   SELECT CEIL(COUNT(*)/10.0)
	FROM qna q JOIN goods g 
	ON q.goods_no = g.goods_no
	WHERE q.type != '관리자답변'

		AND q.status = #{status}


		AND q.id = #{id}

SELECT qna_no, parent_no, type, subject, content, status, id, is_secret, TO_CHAR(CREATED_AT, 'yyyy-mm-dd') AS dbday, goods_no
FROM qna
WHERE qna_no = #{parent_no}

mapper.update:
UPDATE qna
 SET parent_no = #{parent_no}
   , status = #{status}
WHERE qna_no = #{qna_no}

UPDATE qna
 SET content = #{content}
WHERE qna_no = #{qna_no}
